import pytest

class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if not self.is_empty():
            return self.items.pop()
        else:
            raise IndexError("Pilha vazia")

    def peek(self):
        if not self.is_empty():
            return self.items[-1]
        else:
            raise IndexError("Pilha vazia")

    def is_empty(self):
        return len(self.items) == 0

def test_push_pop():
    stack = Stack()
    stack.push(1)
    assert stack.pop() == 1
    assert stack.is_empty()

def test_pop_vazia():
    stack = Stack()
    with pytest.raises(IndexError):
        stack.pop()

def test_peek_vazia():
    stack = Stack()
    with pytest.raises(IndexError):
        stack.peek()

def test_multiplos_elementos():
    stack = Stack()
    stack.push(1)
    stack.push(2)
    assert stack.pop() == 2
    assert stack.pop() == 1
    assert stack.is_empty()
